beforeExample:
package com.example;

import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.IPath;

public class MyResourceChecker {
    public boolean checkResource(IResource resource) {
        if (resource != null && resource.isDerived()) {
            return true;
        }
        return false;
    }

    public boolean anotherCheck(IResource res) {
        return res.isDerived();
    }
}

afterExample:
package com.example;

import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.IPath;

public class MyResourceChecker {
    public boolean checkResource(IResource resource) {
        if (resource != null && resource.isDerived(org.eclipse.core.resources.IResource.CHECK_ANCESTORS)) {
            return true;
        }
        return false;
    }

    public boolean anotherCheck(IResource res) {
        return res.isDerived(org.eclipse.core.resources.IResource.CHECK_ANCESTORS);
    }
}

