package com.example;

import java.io.File;
import java.nio.file.Path;

public class NegativeExample {
    public boolean checkFile(File file) {
        // Should not match File.isAbsolute()
        return file.isAbsolute();
    }

    public boolean checkPath(Path path) {
        // Should not match Path.isAbsolute()
        return path.isAbsolute();
    }

    public boolean checkDerived(MyCustomResource customResource) {
        // Should not match if MyCustomResource.isDerived() exists but isn't IResource
        return customResource.isDerived();
    }
}

class MyCustomResource {
    public boolean isDerived() { return false; }
}
